SELECT

FROM sys_notify_todo_target

    AND field_id = #{model.fieldId}
    AND field_todo_id = #{model.fieldTodoId}
    AND field_user_id = #{model.fieldUserId}
    AND field_is_done = #{model.fieldIsDone}
    AND field_is_star = #{model.fieldIsStar}
    AND field_is_del = #{model.fieldIsDel}

ORDER BY field_receive_time DESC


    LIMIT #{pages.pageSize} OFFSET #{offset}

SELECT
    t.field_id, t.field_todo_id, t.field_is_done, t.field_is_star,
    t.field_receive_time, t.field_done_time, t.field_star_time,
    m.field_name, m.field_model_name, m.field_notify_type, m.field_url
FROM sys_notify_todo_target t
LEFT JOIN sys_notify_todo m ON m.field_id = t.field_todo_id

    t.field_user_id = #{userId}
    AND t.field_is_del = 0
    AND m.field_notify_type = #{model.fieldNotifyType}
    AND m.field_model_name = #{model.fieldModelName}
    AND t.field_is_star = #{model.fieldIsStar}
    AND t.field_is_done = #{model.fieldIsDone}
    AND m.field_name LIKE CONCAT('%', #{model.fieldName}, '%')
    AND t.field_receive_time >= #{model.fieldReceiveTimeStart}
    AND t.field_receive_time <= #{model.fieldReceiveTimeEnd}

ORDER BY

    t.field_receive_time
    t.field_receive_time


    ASC
    DESC



    LIMIT #{pages.pageSize} OFFSET #{offset}

SELECT COUNT(*)
FROM sys_notify_todo_target t
LEFT JOIN sys_notify_todo m ON m.field_id = t.field_todo_id

    t.field_user_id = #{userId}
